<?php
use App\Application\Tenancy\TenantLifecycleService;use App\Models\Tenant;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;
uses(RefreshDatabase::class);
test('tenant activation records immutable history',function(){$actor=User::factory()->create();$tenant=Tenant::create(['type'=>'BROKER','legal_name'=>'Broker','slug'=>'broker-lifecycle','status'=>'PENDING','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);app(TenantLifecycleService::class)->transition($tenant,'ACTIVE','LEGAL_VERIFIED','MINFI registration verified',$actor);expect($tenant->refresh()->status)->toBe('ACTIVE');$this->assertDatabaseHas('tenant_status_history',['tenant_id'=>$tenant->id,'from_status'=>'PENDING','to_status'=>'ACTIVE','reason_code'=>'LEGAL_VERIFIED']);});
test('invalid tenant status transitions fail closed',function(){$actor=User::factory()->create();$tenant=Tenant::create(['type'=>'BROKER','legal_name'=>'Closed','slug'=>'closed-broker','status'=>'CLOSED','country_code'=>'CM','currency'=>'XAF','primary_locale'=>'en','settings'=>[]]);expect(fn()=>app(TenantLifecycleService::class)->transition($tenant,'ACTIVE','RESTORE','Attempted restore',$actor))->toThrow(ValidationException::class);});
